-- UNAPPLIED. Standalone D1 public-capture authority core only. NO RPC/runtime
-- adoption or schema_migrations marker is enabled by this file.
-- A separate authorized provisioning transaction must insert ONE authority row
-- with exact existing database UUID/binding nonce, explicit epoch/key_tag, and a
-- checksum of the original metadata view (including all existing worlds/aliases).
-- Core constructors/read paths NEVER initialize/reset/repair missing authority.
-- No company records, paid ledger or upstream/client allowance belongs here.
CREATE TABLE world_capture_authority (singleton INTEGER PRIMARY KEY CHECK(singleton=1), protocol INTEGER NOT NULL CHECK(protocol=1), database_uuid TEXT NOT NULL CHECK(length(database_uuid)=36), binding_nonce TEXT NOT NULL CHECK(length(binding_nonce)=32 AND binding_nonce NOT GLOB '*[^0-9a-f]*'), authority_epoch TEXT NOT NULL CHECK(length(authority_epoch)=32 AND authority_epoch NOT GLOB '*[^0-9a-f]*'), key_tag TEXT NOT NULL CHECK(length(key_tag)=64 AND key_tag NOT GLOB '*[^0-9a-f]*'), sequence INTEGER NOT NULL CHECK(typeof(sequence)='integer' AND sequence BETWEEN 0 AND 9007199254740991), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision BETWEEN 0 AND 9007199254740991), checksum TEXT NOT NULL CHECK(length(checksum)=64 AND checksum NOT GLOB '*[^0-9a-f]*'));
CREATE TABLE world_capture_barriers (repo TEXT PRIMARY KEY CHECK(length(repo) BETWEEN 3 AND 140 AND repo=lower(repo) AND repo NOT GLOB '*[^a-z0-9_./-]*'), sequence INTEGER NOT NULL CHECK(typeof(sequence)='integer' AND sequence BETWEEN 1 AND 9007199254740991), denied INTEGER NOT NULL CHECK(typeof(denied)='integer' AND denied IN (0,1)));
CREATE TABLE world_capture_generations (handle_hash TEXT PRIMARY KEY CHECK(length(handle_hash)=64 AND handle_hash NOT GLOB '*[^0-9a-f]*'), repo TEXT NOT NULL, start_canonical TEXT NOT NULL, start_sequence INTEGER NOT NULL CHECK(typeof(start_sequence)='integer' AND start_sequence BETWEEN 0 AND 9007199254740991), explicit INTEGER NOT NULL CHECK(typeof(explicit)='integer' AND explicit IN (0,1)), status TEXT NOT NULL CHECK(status IN ('active','committed','deny-pending','denied')), operation_hash TEXT, roots TEXT, targets TEXT, accepted_sequence INTEGER, ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 1 AND 9007199254740991), CHECK((status='active' AND operation_hash IS NULL AND roots IS NULL AND targets IS NULL AND accepted_sequence IS NULL) OR (status<>'active' AND operation_hash IS NOT NULL AND length(operation_hash)=64 AND operation_hash NOT GLOB '*[^0-9a-f]*' AND roots IS NOT NULL AND json_valid(roots) AND json_type(roots)='array' AND json_array_length(roots) BETWEEN 1 AND 2 AND targets IS NOT NULL AND json_valid(targets) AND json_type(targets)='array' AND json_array_length(targets)<=204 AND typeof(accepted_sequence)='integer' AND accepted_sequence BETWEEN 0 AND 9007199254740991)));
-- A persistent constant row lets each CAS assertion throw via CHECK INSIDE the
-- D1 batch without an unsafe changes=0 result or a dangling guard-cleanup step.
CREATE TABLE world_capture_guard (singleton INTEGER PRIMARY KEY CHECK(singleton=1), accepted INTEGER NOT NULL CHECK(accepted=1));
INSERT INTO world_capture_guard VALUES(1,1);
